select id, product_id, revenue, lag(revenue, 1, 0) over w_running as prev_revenue, lag(revenue, 2) over (partition by product_id order by revenue, id) as prev_revenue_2, stddev_samp(units) over w_part as store_id_stddev_samp_units, last_value(units) ignore nulls over w_hist as last_known_units, count(units) over (partition by product_id) as product_id_count_units from store_sales where store_id in (2, 3, 4, 5) window w_running as (order by sale_date, id), w_part as (partition by store_id), w_hist as (order by revenue, id rows between unbounded preceding and current row)
